/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { BiomoleculesScreen } from "../../src/biomolecules/BiomoleculesScreen.js";
import { CrystalsScreen } from "../../src/crystals/CrystalsScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import MolScopeColors from "../../src/MolScopeColors.js";
import { MoleculesScreen } from "../../src/molecules/MoleculesScreen.js";
import { MolScopePreferencesModel } from "../../src/preferences/MolScopePreferencesModel.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from molScopeQueryParameters.
  const simPreferences = new MolScopePreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new MoleculesScreen(
      { perspectiveProperty: simPreferences.perspectiveProperty },
      {
        name: stringManager.getScreenNames().moleculesStringProperty,
        tandem: Tandem.ROOT.createTandem("moleculesScreen"),
        backgroundColorProperty: MolScopeColors.backgroundColorProperty,
      },
    ),
    new BiomoleculesScreen(
      { perspectiveProperty: simPreferences.perspectiveProperty },
      {
        name: stringManager.getScreenNames().biomoleculesStringProperty,
        tandem: Tandem.ROOT.createTandem("biomoleculesScreen"),
        backgroundColorProperty: MolScopeColors.backgroundColorProperty,
      },
    ),
    new CrystalsScreen(
      { perspectiveProperty: simPreferences.perspectiveProperty },
      {
        name: stringManager.getScreenNames().crystalsStringProperty,
        tandem: Tandem.ROOT.createTandem("crystalsScreen"),
        backgroundColorProperty: MolScopeColors.backgroundColorProperty,
      },
    ),
  ];

  return { screens, tracked: { MolScopeColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
